const express = require('express');
const router = express.Router();
const { Client } = require('@opensearch-project/opensearch');
const client = new Client({ node: process.env.OPENSEARCH_URL });

router.post('/api/knowledge-base/knn-search', authenticateEmployee, async (req, res) => {
  const { queryVector, topK } = req.body;

  const osResponse = await client.search({
    index: 'internal_knowledge_base',
    body: {
      size: topK || 5,
      query: {
        bool: {
          must: [
            {
              knn: {
                embedding: {
                  vector: queryVector,
                  k: topK || 5
                }
              }
            }
          ],
          filter: [
            { terms: { allowed_groups: req.user.groups } }
          ]
        }
      }
    }
  });

  const results = osResponse.body.hits.hits.map(h => ({
    title: h._source.title,
    content: h._source.content,
    classification: h._source.classification
  }));
  return res.json({ results });
});
